{"implementation":"def solve(case):
    segments = case["segments"]
    budget = case["budget"]
    allocations = [int(segment["minimum"]) for segment in segments]
    remaining = max(0, int(budget) - sum(allocations))
    order = sorted(range(len(segments)), key=lambda i: (-int(segments[i]["importance"]), i))
    for i in order:
        extra = min(remaining, int(segments[i]["capacity"]) - allocations[i])
        if extra > 0:
            allocations[i] += extra
            remaining -= extra
        if remaining == 0:
            break
    return {
        "allocations": allocations,
        "by_name": {segment["name"]: allocations[i] for i, segment in enumerate(segments)},
        "total": sum(allocations)
    }"}
